    14→/**
    15→ * Minimal test-only scheduler that mirrors the daemon's ShadowSyncScheduler
    16→ * but imports from the test-accessible path. This avoids the daemon's relative
    17→ * import path (`../../parser/shadow.js`) which vitest cannot resolve.
    18→ *
    19→ * AC: @config-shadow ac-12
    20→ */
    21→class TestShadowSyncScheduler {
    22→  private timer: ReturnType<typeof setInterval> | null = null;
    23→  private running = false;
    24→  private readonly worktreeDir: string;
    25→  private readonly intervalMs: number;
    26→  private readonly shadowOptions?: ShadowOptions;
    27→
    28→  constructor(options: { worktreeDir: string; intervalSeconds: number; shadowOptions?: ShadowOptions }) {
    29→    this.worktreeDir = options.worktreeDir;
    30→    this.intervalMs = options.intervalSeconds * 1000;
    31→    this.shadowOptions = options.shadowOptions;
    32→  }
    33→
    34→  start(): void {
    35→    if (this.intervalMs <= 0 || this.timer !== null) return;
    36→    console.log(`[daemon] Shadow sync scheduler started (interval: ${this.intervalMs / 1000}s)`);
    37→    this.timer = setInterval(() => {
    38→      this.syncOnce().catch((err) => console.error('[daemon] Shadow sync error:', err));
    39→    }, this.intervalMs);
    40→    if (this.timer && typeof this.timer === 'object' && 'unref' in this.timer) {
    41→      this.timer.unref();
    42→    }
    43→  }
    44→
    45→  stop(): void {
    46→    if (this.timer !== null) {
    47→      clearInterval(this.timer);
    48→      this.timer = null;
    49→      console.log('[daemon] Shadow sync scheduler stopped');
    50→    }
    51→  }
    52→
    53→  async syncOnce(): Promise<void> {
    54→    if (this.running) return;
    55→    const hasTracking = await hasRemoteTracking(this.worktreeDir, this.shadowOptions);
    56→    if (!hasTracking) return;
    57→    this.running = true;
    58→    try {
    59→      const result = await shadowPull(this.worktreeDir, this.shadowOptions);
    60→      if (result.pulled) {
    61→        console.log('[daemon] Shadow sync: pulled remote changes');
    62→      }
    63→      if (result.hadConflict) {
    64→        console.warn('[daemon] Shadow sync: conflict detected. Run `kspec shadow resolve` to fix.');
    65→      }
    66→    } finally {
    67→      this.running = false;
    68→    }
    69→  }
    70→}
