// Check if running from inside the shadow worktree
// AC: @config-shadow ac-8 — pass configured directory for detection
const mainProjectRoot = await detectRunningFromShadowWorktree(
  cwd,
  config.shadow.directory,
);
if (mainProjectRoot) {
  throw new ShadowError(
    errors.project.runningFromShadow,
    "RUNNING_FROM_SHADOW",
    `Run from project root: cd ${path.relative(cwd, mainProjectRoot) || mainProjectRoot}`,
  );
}

// Try to detect shadow branch first
// AC: @config-shadow ac-1 ac-2 — use configured branch/directory names
const shadow = await detectShadow(cwd, {
  branchName: config.shadow.branch,
  directory: config.shadow.directory,
});

if (shadow?.enabled) {
  // Shadow mode: use .kspec/ for everything
  const specDir = shadow.worktreeDir;

  // AC: @config-shadow ac-11 — pre-read shadow pull to pick up remote changes
  // before CLI read operations (task list, session start, etc.)
  // Skip when KSPEC_NO_SYNC is set (tests, offline) or KSPEC_SPEC_DIR is overridden
  if (!process.env.KSPEC_NO_SYNC) {
    try {
      const tracked = await hasRemoteTracking(specDir);
      if (tracked) {
        const syncResult = await shadowPull(specDir);
        if (syncResult.hadConflict) {
          console.error(
            "Warning: Shadow sync conflict detected. Run `kspec shadow resolve` to fix.",
          );
          console.error("Continuing with local state...");
        }
      }
    } catch {
      // Pre-read pull is best-effort — don't fail the command
    }
  }

  const manifestPath = await findManifestInDir(specDir);

  let manifest: Manifest | null = null;
  if (manifestPath) {
    try {
      const rawManifest = await readYamlFile<unknown>(manifestPath);
      manifest = parseManifestWithWarnings(rawManifest);
    } catch {
      // Manifest exists but may be invalid
    }
  }

  return {
    rootDir: shadow.projectRoot,
    specDir,
    manifestPath,
    manifest,
    shadow,
    config,
  };
}

